def solve_unique_counts(text):
    tokens = text.split()
    n = int(tokens[0])
    counts = {}
    for code in tokens[1:1 + n]:
        counts[code] = counts.get(code, 0) + 1
    used = set()
    removed = 0
    for c in counts.values():
        k = c
        while k in used:
            k -= 1
        removed += c - k
        used.add(k)
    return str(removed)

def solve_unique_counts(text):
    tokens = text.split()
    n = int(tokens[0])
    counts = {}
    for code in tokens[1:1 + n]:
        counts[code] = counts.get(code, 0) + 1
    used = set()
    removed = 0
    for c in counts.values():
        if c in used:
            removed += c
        else:
            used.add(c)
    return str(removed)

def solve_unique_counts(text):
    lines = text.split("\n")
    n = int(lines[0])
    codes = lines[1].split(" ") if n else []
    counts = {}
    for code in codes:
        counts[code] = counts.get(code, 0) + 1
    removed = 0
    cap = None
    for c in sorted(counts.values(), reverse=True):
        keep = c if cap is None else min(c, cap)
        removed += c - keep
        cap = max(keep - 1, 0)
    return str(removed)
